#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n,m;cin>>n>>m;vector<string>a(n);for(auto&s:a)cin>>s;vector<int>id(n*m,-1);int count=0;for(int i=0;i<n*m;i++)if(a[i/m][i%m]=='#')id[i]=count++;if(count<=2){cout<<-1<<'\n';return 0;}vector<vector<int>>g(count);for(int r=0;r<n;r++)for(int c=0;c<m;c++)if(id[r*m+c]>=0)for(auto[dr,dc]:vector<pair<int,int>>{{1,0},{-1,0},{0,1},{0,-1}}){int x=r+dr,y=c+dc;if(x>=0&&x<n&&y>=0&&y<m&&id[x*m+y]>=0)g[id[r*m+c]].push_back(id[x*m+y]);}vector<int>dfn(count),low(count);int clock=0;bool articulation=false;function<void(int,int)>dfs=[&](int u,int parent){dfn[u]=low[u]=++clock;int children=0;for(int v:g[u])if(!dfn[v]){children++;dfs(v,u);low[u]=min(low[u],low[v]);if(parent>=0&&low[v]>=dfn[u])articulation=true;}else if(v!=parent)low[u]=min(low[u],dfn[v]);if(parent<0&&children>1)articulation=true;};dfs(0,-1);cout<<(articulation?1:2)<<'\n';}
